  --mist:#c3cac6;--faint:#8a928e;--red:#f2665c;
  --display:ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;color-scheme:dark}
body{background:var(--field);color:var(--chalk);font:400 15px/1.45 var(--display);margin:0}
main{max-width:640px;margin:0 auto;padding-block:20px 40px;
  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
h1{margin:0;font:700 13px/1 var(--display);letter-spacing:.14em;text-transform:uppercase;color:var(--gold)}
.meta{margin:6px 0 18px;color:var(--faint);font-size:13px;font-variant-numeric:tabular-nums}
ol{list-style:none;margin:0;padding:0;display:grid;gap:8px}
li{display:grid;grid-template-columns:auto 1fr;gap:2px 12px;padding:12px 14px;background:var(--panel);
  border:1px solid var(--edge);border-radius:8px}
.when{grid-row:span 3;min-width:62px;color:var(--gold);font-weight:700;font-variant-numeric:tabular-nums}
li.late{border-color:var(--red)} li.late .when{color:var(--red)}
.nm{font-weight:600;overflow-wrap:anywhere;min-width:0}
.st{color:var(--mist);font-size:14px} .tc{color:var(--faint);font-size:12.5px}
footer{margin-top:20px;color:var(--faint);font-size:12.5px}
